import pyAether as pyScript

def safe_cleanup(lib_name, confirmed=False):
    lib = pyScript.dmGetObj(lib_name)
    if lib is None:
        return False, "library not found"
    if not lib.isWriteable:
        return False, "library is read-only"
    if not confirmed:
        return False, "deletion not confirmed"
    result = pyScript.dmDeleteObj(lib)
    return result, "deleted" if result else "delete failed"

ok, msg = safe_cleanup("scratch_lib", confirmed=True)
print("Cleanup:", msg)

import pyAether as pyScript

lib = pyScript.dmGetObj("tech_lib")
if lib is None:
    print("Library not found")
else:
    for cell in lib.cells:
        cell_obj = pyScript.dmGetObj("tech_lib", cell.name)
        if cell_obj is None:
            continue
        for view in cell_obj.views:
            vobj = pyScript.dmGetObj("tech_lib", cell.name, view.name)
            if vobj is not None:
                vt = str(pyScript.dmGetObjType(vobj))
                print("  %s/%s/%s [%s]" % (lib.name, cell.name, view.name, vt))
